// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] calldata tos, uint256 v) public {
        vm.assume(tos.length > 0);
        // bare address has no code, so the low-level transferFrom call succeeds
        bool ok;
        try c.transfer(from, from, tos, v) returns (bool ret) { ok = ret; } catch { ok = false; }
        assertTrue(ok);
    }
}
